<?php
require_once __DIR__ . '/../app/layout.php';
$u=require_role(['admin','ngo']); if($u['role']==='ngo' && $u['verification_status']!=='verified'){http_response_code(403);exit('Only verified NGOs can respond to emergency broadcasts.');} $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=(string)($_POST['action']??'');
 try {
  if($action==='create' && $u['role']==='admin'){
   $title=trim((string)($_POST['title']??''));$area=trim((string)($_POST['area_code']??''));$description=trim((string)($_POST['description']??''));$urgency=(string)($_POST['urgency']??'high');$quantity=(float)($_POST['target_quantity_kg']??0);$hours=(int)($_POST['hours']??24);
   if($title===''||$area===''||text_length($title)>180||text_length($area)>180||!in_array($urgency,['low','normal','high','critical'],true)||$quantity<0||$quantity>1000000||$hours<1||$hours>168)throw new RuntimeException('Check title, area, urgency, quantity and expiry (1–168 hours).');
   $q=$pdo->prepare("INSERT INTO emergency_broadcasts(title,description,area_code,urgency,target_quantity_kg,expires_at,created_by) VALUES(?,?,?,?,?,DATE_ADD(NOW(),INTERVAL ? HOUR),?)");$q->execute([$title,$description?:null,$area,$urgency,$quantity,$hours,$u['id']]);$id=(int)$pdo->lastInsertId();
   $n=$pdo->prepare("INSERT INTO notifications(user_id,title,message) SELECT id,?,? FROM users WHERE is_active=1 AND verification_status='verified' AND role='ngo'");$n->execute(['Emergency food rescue: '.$title,'Area: '.$area.'. Urgency: '.$urgency.'. Open the Emergency Center to respond.']);
   audit((int)$u['id'],'emergency_broadcast_created','emergency_broadcasts',$id,$area); flash('Emergency broadcast created and verified NGOs notified.');
  } elseif($action==='respond' && $u['role']==='ngo'){
   $id=(int)($_POST['broadcast_id']??0);$status=(string)($_POST['response_status']??'available');$qty=(float)($_POST['available_quantity_kg']??0);$message=trim((string)($_POST['message']??''));
   if(!in_array($status,['available','accepted','unable'],true)||$qty<0||$qty>1000000||text_length($message)>1000)throw new RuntimeException('Invalid response details.');
   $check=$pdo->prepare("SELECT id FROM emergency_broadcasts WHERE id=? AND status='open' AND expires_at>NOW()");$check->execute([$id]);if(!$check->fetchColumn())throw new RuntimeException('This broadcast is closed or expired.');
   $q=$pdo->prepare("INSERT INTO broadcast_responses(broadcast_id,organisation_id,response_status,available_quantity_kg,message) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE response_status=VALUES(response_status),available_quantity_kg=VALUES(available_quantity_kg),message=VALUES(message),responded_at=NOW()");$q->execute([$id,$u['id'],$status,$qty,$message?:null]);audit((int)$u['id'],'emergency_broadcast_response','emergency_broadcasts',$id,$status);flash('Your emergency response has been saved.');
  } elseif($action==='close' && $u['role']==='admin'){
   $id=(int)($_POST['broadcast_id']??0);$q=$pdo->prepare("UPDATE emergency_broadcasts SET status='closed' WHERE id=? AND status IN ('open','paused')");$q->execute([$id]);if(!$q->rowCount())throw new RuntimeException('Broadcast was already closed or not found.');audit((int)$u['id'],'emergency_broadcast_closed','emergency_broadcasts',$id);flash('Broadcast closed.');
  } else throw new RuntimeException('Action not allowed.');
 }catch(Throwable $e){flash($e instanceof RuntimeException?$e->getMessage():'Could not save this action. Verify that the new migration has been imported.','error');}
 redirect('emergency_center.php');
}
$rows=$pdo->query("SELECT b.*,u.name AS creator,(SELECT COUNT(*) FROM broadcast_responses br WHERE br.broadcast_id=b.id) AS response_count FROM emergency_broadcasts b JOIN users u ON u.id=b.created_by WHERE b.status IN ('open','paused') AND b.expires_at>NOW() ORDER BY FIELD(b.urgency,'critical','high','normal','low'),b.expires_at ASC LIMIT 100")->fetchAll();
$myResponses=[];if($u['role']==='ngo'){$q=$pdo->prepare('SELECT * FROM broadcast_responses WHERE organisation_id=?');$q->execute([$u['id']]);foreach($q->fetchAll() as $r)$myResponses[(int)$r['broadcast_id']]=$r;}
page_header('Emergency food rescue'); ?>
<div class="page-intro"><div class="eyebrow">TIME-BOUND COORDINATION</div><h1>Emergency <em>food rescue.</em></h1><p>Coordinate verified NGO responses to urgent food needs. Broadcasts expire automatically and do not replace emergency services.</p></div>
<?php if($u['role']==='admin'): ?><section class="section"><div class="section-heading"><div><div class="eyebrow">ADMIN</div><h2>Create a broadcast</h2></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create"><label>Title<input name="title" maxlength="180" required></label><label>Area / district<input name="area_code" maxlength="180" required placeholder="e.g. Sylhet Sadar"></label><label>Urgency<select name="urgency"><option value="critical">Critical</option><option value="high" selected>High</option><option value="normal">Normal</option><option value="low">Low</option></select></label><label>Target food (kg)<input name="target_quantity_kg" type="number" min="0" max="1000000" step="0.1" value="0"></label><label>Expires in hours<input name="hours" type="number" min="1" max="168" value="24" required></label><label class="full">Description<textarea name="description" rows="3" maxlength="5000"></textarea></label><div class="full"><button class="btn">Create emergency broadcast</button></div></form></section><?php endif; ?>
<section class="section"><div class="section-heading"><div><div class="eyebrow">ACTIVE BROADCASTS</div><h2>Open requests</h2></div></div><div class="delivery-list">
<?php foreach($rows as $r): ?><article class="delivery-card"><div class="delivery-top"><div><div class="eyebrow">BROADCAST #<?= (int)$r['id'] ?> · <?= e($r['area_code']) ?></div><h3><?= e($r['title']) ?></h3></div><?= status_badge($r['urgency']) ?></div><p><?= nl2br(e($r['description']??'')) ?></p><p><strong>Target:</strong> <?= e((string)$r['target_quantity_kg']) ?> kg · <strong>Expires:</strong> <?= e(date('d M, g:i A',strtotime($r['expires_at']))) ?> · <strong>Responses:</strong> <?= (int)$r['response_count'] ?></p>
<?php if($u['role']==='ngo'): $mr=$myResponses[(int)$r['id']]??null; ?><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="respond"><input type="hidden" name="broadcast_id" value="<?= (int)$r['id'] ?>"><label>Response<select name="response_status"><option value="available" <?= ($mr['response_status']??'')==='available'?'selected':'' ?>>Available to help</option><option value="accepted" <?= ($mr['response_status']??'')==='accepted'?'selected':'' ?>>Can take this request</option><option value="unable" <?= ($mr['response_status']??'')==='unable'?'selected':'' ?>>Unable to help</option></select></label><label>Food available (kg)<input type="number" min="0" max="1000000" step="0.1" name="available_quantity_kg" value="<?= e((string)($mr['available_quantity_kg']??0)) ?>"></label><label class="full">Message<textarea name="message" maxlength="1000" rows="2"><?= e($mr['message']??'') ?></textarea></label><div class="full"><button class="btn btn-sm">Submit response</button></div></form><?php endif; ?>
<?php if($u['role']==='admin'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="close"><input type="hidden" name="broadcast_id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-danger">Close broadcast</button></form><?php endif; ?></article><?php endforeach; if(!$rows): ?><div class="empty-state"><div>🆘</div><h3>No active emergency broadcasts</h3><p>New verified emergency coordination requests will appear here.</p></div><?php endif; ?></div></section>
<?php page_footer(); ?>
